import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_CUDA_SRC = r'''
#include <torch/extension.h>
#include <ATen/Dispatch.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>

#ifndef WARP_SIZE
#define WARP_SIZE 32
#endif

template <typename T>
__device__ __forceinline__ float to_float_dev(T v) { return (float)v; }

template <typename scalar_t, int ROWS_PER_BLOCK>
__global__ __launch_bounds__(ROWS_PER_BLOCK*32, 4)
void softmax_warp_rows_kernel(const scalar_t* __restrict__ x,
                              scalar_t* __restrict__ y,
                              int N, int D) {
    int tid = threadIdx.x;
    int lane = tid & 31;
    int warp = tid >> 5;
    int row = blockIdx.x * ROWS_PER_BLOCK + warp;
    if (row >= N) return;

    const scalar_t* __restrict__ row_x = x + (long long)row * D;
    scalar_t* __restrict__ row_y = y + (long long)row * D;

    // Pass 1: row maximum.
    float m = -FLT_MAX;
    #pragma unroll 1
    for (int col = lane; col < D; col += 32) {
        float v = (float)row_x[col];
        m = fmaxf(m, v);
    }
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
        m = fmaxf(m, __shfl_xor_sync(0xffffffffu, m, off));
    }

    // Pass 2: sum exp(x - max).
    float s = 0.0f;
    #pragma unroll 1
    for (int col = lane; col < D; col += 32) {
        s += __expf((float)row_x[col] - m);
    }
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
        s += __shfl_xor_sync(0xffffffffu, s, off);
    }
    float inv_s = 1.0f / s;

    // Pass 3: normalize.
    #pragma unroll 1
    for (int col = lane; col < D; col += 32) {
        float out = __expf((float)row_x[col] - m) * inv_s;
        row_y[col] = (scalar_t)out;
    }
}

// One CTA per row for wide rows. 256 threads gives enough parallelism without
// excessive synchronization overhead for the stress shapes normally used here.
template <typename scalar_t, int BLOCK_THREADS>
__global__ __launch_bounds__(BLOCK_THREADS, 2)
void softmax_block_rows_kernel(const scalar_t* __restrict__ x,
                               scalar_t* __restrict__ y,
                               int N, int D) {
    int row = blockIdx.x;
    if (row >= N) return;
    int tid = threadIdx.x;
    const scalar_t* __restrict__ row_x = x + (long long)row * D;
    scalar_t* __restrict__ row_y = y + (long long)row * D;

    float m = -FLT_MAX;
    #pragma unroll 1
    for (int col = tid; col < D; col += BLOCK_THREADS) {
        m = fmaxf(m, (float)row_x[col]);
    }

    // reduce max: first within warps, then among warp leaders.
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
        m = fmaxf(m, __shfl_xor_sync(0xffffffffu, m, off));
    }
    __shared__ float warp_vals[32];
    int lane = tid & 31;
    int warp = tid >> 5;
    if (lane == 0) warp_vals[warp] = m;
    __syncthreads();
    if (warp == 0) {
        m = (lane < (BLOCK_THREADS + 31) / 32) ? warp_vals[lane] : -FLT_MAX;
        #pragma unroll
        for (int off = 16; off > 0; off >>= 1) {
            m = fmaxf(m, __shfl_xor_sync(0xffffffffu, m, off));
        }
        if (lane == 0) warp_vals[0] = m;
    }
    __syncthreads();
    m = warp_vals[0];

    float s = 0.0f;
    #pragma unroll 1
    for (int col = tid; col < D; col += BLOCK_THREADS) {
        s += __expf((float)row_x[col] - m);
    }
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
        s += __shfl_xor_sync(0xffffffffu, s, off);
    }
    if (lane == 0) warp_vals[warp] = s;
    __syncthreads();
    if (warp == 0) {
        s = (lane < (BLOCK_THREADS + 31) / 32) ? warp_vals[lane] : 0.0f;
        #pragma unroll
        for (int off = 16; off > 0; off >>= 1) {
            s += __shfl_xor_sync(0xffffffffu, s, off);
        }
        if (lane == 0) warp_vals[0] = s;
    }
    __syncthreads();
    s = warp_vals[0];
    float inv_s = 1.0f / s;

    #pragma unroll 1
    for (int col = tid; col < D; col += BLOCK_THREADS) {
        row_y[col] = (scalar_t)(__expf((float)row_x[col] - m) * inv_s);
    }
}

