                x.data_ptr<scalar_t>(), y.data_ptr<scalar_t>(), N, D);
        } else {
            constexpr int BT = 256;
            softmax_block_rows_kernel<scalar_t, BT><<<N, BT, 0, stream>>>(
                x.data_ptr<scalar_t>(), y.data_ptr<scalar_t>(), N, D);
        }
    });
